-- Ejecuta este script en Supabase → SQL Editor.
-- Si ya tienes TECNICA, GRADO y ESTUDIANTE, revisa antes de ejecutar para no duplicar estructura.
create table if not exists public."TECNICA" (
  "ID_TECNICA" bigint generated by default as identity primary key,
  "NOMBRE_TECNICA" text not null unique
);

create table if not exists public."GRADO" (
  "ID_GRADO" bigint generated by default as identity primary key,
  "NOMBRE_GRADO" text not null unique
);

create table if not exists public."ESTUDIANTE" (
  "ID_ESTUDIANTE" bigint generated by default as identity primary key,
  "NOMBRE_COMPLETO" text not null,
  "NUMERO_DE_LISTA" integer not null check ("NUMERO_DE_LISTA" > 0),
  "CORREO" text not null unique,
  "ID_TECNICA" bigint not null references public."TECNICA"("ID_TECNICA"),
  "ID_GRADO" bigint not null references public."GRADO"("ID_GRADO"),
  "CONTRASEÑA" text not null,
  "FECHA_REGISTRO" timestamptz not null default now()
);

alter table public."ESTUDIANTE" add column if not exists "ASISTIO" boolean not null default false;

create index if not exists estudiante_correo_idx on public."ESTUDIANTE" (lower("CORREO"));

-- Ajusta estos catálogos a los nombres oficiales de tu centro.
insert into public."TECNICA" ("NOMBRE_TECNICA") values
  ('Informática'), ('Mercadeo A'), ('Mercadeo B'), ('Contabilidad A'),
  ('Contabilidad B'), ('Electricidad'), ('Electrónica'), ('Gastronomía')
on conflict ("NOMBRE_TECNICA") do nothing;

insert into public."GRADO" ("NOMBRE_GRADO") values
  ('4to'), ('5to'), ('6to')
on conflict ("NOMBRE_GRADO") do nothing;

-- El backend usa la clave secreta de Supabase y valida los permisos. No expongas esa clave en el navegador.
